package android.provider;import android.net.Uri;import android.content.ContentResolver;import java.io.*;
public final class DocumentsContract {public static final class Document {public static final String COLUMN_SIZE="size",COLUMN_LAST_MODIFIED="time",COLUMN_DOCUMENT_ID="id",COLUMN_DISPLAY_NAME="name",COLUMN_MIME_TYPE="mime",MIME_TYPE_DIR="directory";} public static String getTreeDocumentId(Uri u){return path(u);}public static String getDocumentId(Uri u){return path(u);}public static Uri buildDocumentUriUsingTree(Uri t,String id){return Uri.parse("file:"+id);}public static Uri buildChildDocumentsUriUsingTree(Uri t,String id){return Uri.parse("children:"+id);} public static String path(Uri u){String s=u.toString();return s.substring(s.indexOf(':')+1);} public static Uri createDocument(ContentResolver r,Uri p,String m,String n)throws IOException{return r.createDocument(p,m,n);}public static boolean deleteDocument(ContentResolver r,Uri u)throws IOException{return r.deleteDocument(u);} }
